		private void cmdAData_CommandExecute(object parameter)
		{
			DisplayForm(new DisplayFormEventArgs
			{
				FormProgId = "MMZieglerna.MMZieglerna_React_Param",
				HelpFile = "polyfrms.hlp",
				HelpId = 88,
				ShowPrompts = false,
				CompleteDataPaths = new string[1] { "ZNRAT" }
			});
		}

		private void cmdNew_CommandExecute(object parameter)
		{
			if (CheckDuplicate())
			{
				DeleteNewChild();
			}
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.ZINTYPE", "child_count"));
			string value = "#0";
			if (num.HasValue)
			{
				value = "#" + num.Value;
			}
			else
			{
				num = 0;
			}
			AddChild("@main.Input.ZINTYPE", num.Value);
			ResolveUpdateParameter("CURRXN", value);
			ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Compnent_1);
			ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Compnent_2);
			cmdNew_Enabled = false;
			cmdAClose_Enabled = false;
		}

		private void cmdAClose_CommandExecute(object parameter)
		{
			if (CheckDuplicate())
			{
				DeleteNewChild();
			}
			CloseForm();
		}

		private void cmdACancel_CommandExecute(object parameter)
		{
			DeleteNewChild();
			CloseForm();
		}

		protected override void OnUpdateData()
		{
			base.OnUpdateData();
			if (base.IsInitialUpdate)
			{
				PolyRedoLabels();
			}
		}

		private void PolyRedoLabels()
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.ZINTYPE.@CURRXN", "value"));
			string empty = string.Empty;
			string text2 = "";
			string text3 = "";
			string text4 = "";
			string text5 = "";
			bool flag = false;
			switch (text)
			{
			case "CAT-ACTIVATE":
				text2 = " Precat                          ";
				text3 = " Cat";
				text4 = " Precatalyst                   ";
				text5 = "   Catalyst";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Precatalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				flag = true;
				break;
			case "ACT-COCAT":
				text2 = " Cps            +   Ccat           ";
				text3 = " Po";
				text4 = " Potential site   Cocatalyst";
				text5 = "    Vacant site";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Cocatalyst);
				flag = true;
				break;
			case "ACT-EDONOR":
				text2 = " Cps            +   E           ";
				text3 = " Po";
				text4 = " Potential site   Donor";
				text5 = "     Vacant site";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Electron_Donor);
				flag = true;
				break;
			case "ACT-H2":
				text2 = " Cps            +   H2             ";
				text3 = " Po ";
				text4 = " Potential site   Hydrogen";
				text5 = "    Vacant site ";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Hydrogen);
				flag = true;
				break;
			case "ACT-MON":
				text2 = " Cps            +   M           ";
				text3 = " Po             +   M ";
				text4 = " Potential site   Monomer";
				text5 = " Vacant site     Monomer";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Monomer);
				flag = true;
				break;
			case "ACT-SPON":
				text2 = " Cps               ";
				text3 = " Po";
				text4 = " Potential site";
				text5 = "   Vacant site";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				ResolveUpdateParameter("lblAddCid2", "");
				cboAddCid2_Enabled = false;
				flag = true;
				break;
			case "CHAIN-INI":
				text2 = " Po             +   M              ";
				text3 = " P1[M]";
				text4 = " Vacant site     Monomer  ";
				text5 = "  Active Segment";
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Monomer);
				ResolveUpdateParameter("lblAddCid2", "");
				cboAddCid2_Enabled = false;
				flag = true;
