		private bool CheckDuplicate()
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.ZINTYPE.@CURRXN", "value"));
			string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID.@CURRXN", "value"));
			string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1.@CURRXN", "value"));
			string text4 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2.@CURRXN", "value"));
			string dataPath = "@main.Input.ZINTYPE";
			string text5 = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(dataPath, "child_ids"));
			if (array != null)
			{
				List<string> list = new List<string>(array);
				for (int i = 0; i < list.Count; i++)
				{
					if (text5 != list[i])
					{
						string text6 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.ZINTYPE." + list[i], "value"));
						string text7 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID." + list[i], "value"));
						string text8 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1." + list[i], "value"));
						string text9 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2." + list[i], "value"));
						if (text == text6 && text2 == text7 && text3 == text8 && text4 == text9)
						{
							ShowMessageBox(new ShowMessageBoxEventArgs
							{
								Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message50,
								Title = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Add_Reaction,
								MsgBoxButton = MessageBoxButton.OK,
								MsgBoxImage = MessageBoxImage.Asterisk
							});
							return true;
						}
					}
				}
			}
			return false;
		}

		private void DeleteNewChild()
		{
			string text = "@main.Input.ZINTYPE";
			string text2 = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(text, "child_ids"));
			if (array == null)
			{
				return;
			}
			List<string> list = new List<string>(array);
			for (int i = 0; i < list.Count; i++)
			{
				if (text2 == list[i])
				{
					DeleteChild(text, i);
				}
			}
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			if (pd.Name == "cboAddRx_var1" && subPropertyName == "Value")
			{
				if (!string.IsNullOrEmpty(CxsConverter.ValueToString(this.ResolveViewPropertyPath("cboAddRx_var1.Value"))))
				{
					cboAddCid1_Enabled = true;
					cboAddCid2_Enabled = true;
					cmdAClose_Enabled = true;
				}
				PolyRedoLabels();
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}
	}
