		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.ZINTYPE.@CURRXN", "value"));
			_ = string.Empty;
			string content = "";
			string text2 = "";
			string content2 = "";
			string text3 = "";
			string content3 = "";
			string content4 = "";
			string content5 = "";
			string content6 = "";
			bool flag = false;
			switch (text)
			{
			case "CAT-ACTIVATE":
				content = "Precat";
				content2 = "Cat";
				content3 = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_React_Edit_Precatalyst;
				content5 = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_React_Edit_Catalyst;
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Precatalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				flag = true;
				break;
			case "ACT-COCAT":
				content = "Cps";
				text2 = "Ccat";
				content2 = "Po";
				content3 = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_React_Edit_Potential_site;
				content4 = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_React_Edit_Cocatalyst;
				content5 = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_React_Edit_Vacant_site;
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Cocatalyst);
				flag = true;
				break;
			case "ACT-EDONOR":
				content = "Cps";
				text2 = "E";
