				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Monomer1);
				break;
			case "ACT-SPON":
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Catalyst1);
				ResolveUpdateParameter("lblAddCid2", "");
				break;
