		private void cmdGenRxn_CommandExecute(object parameter)
		{
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.SCHANGE", "value"));
			if (CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.ZINTYPE", "child_count")) > 0 && num == 1)
			{
				ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_MSGBox_Message,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					MsgBoxButton = MessageBoxButton.OKCancel,
					MsgBoxImage = MessageBoxImage.Question
				};
				ShowMessageBox(e);
				if (e.DialogResult == MessageBoxResult.Cancel)
				{
					return;
				}
			}
			if (CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.GENRXN", "value")) == "NO")
			{
				ExpandDataPathAndSet("@main.Input.GENRXN", "value", "0", "YES");
			}
			else
			{
				ExpandDataPathAndSet("@main.Input.GENRXN", "value", "0", "NO");
			}
		}

		private void cmdDelete_CommandExecute(object parameter)
		{
			if (parameter != null)
			{
				List<string> list = new List<string>();
				list.Add((CxsConverter.ValueToInt32(parameter).Value - 1).ToString());
				DeleteChildrenByRowIndex("@main.Input.ZINTYPE", list, silently: false, "reaction");
			}
			else if (_selectedRowIndexes != null && _selectedRowIndexes.Count > 0)
			{
				IEnumerable<int> rows = from index in _selectedRowIndexes
					let dataList = grdReacList_GridData as IList
					let itemTemplate = dataList[index] as grdReacList_GridData_ItemTemplate
					orderby index
					select (CxsConverter.ValueToInt32(itemTemplate.ResolveViewPropertyPath("txtRowNo_RowNo.Value")) - 1).GetValueOrDefault();
				IEnumerable<string> ids = from index in _selectedRowIndexes
					let dataList = grdReacList_GridData as IList
					let itemTemplate = dataList[index] as grdReacList_GridData_ItemTemplate
					orderby index
					select CxsConverter.ValueToInt32(itemTemplate.ResolveViewPropertyPath("txtRowNo_RowNo.Value")).GetValueOrDefault().ToString();
				DeleteChildren("@main.Input.ZINTYPE", rows, ids);
			}
		}

		private void cmdRxnAdd_CommandExecute(object parameter)
		{
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.ZINTYPE", "child_count"));
			string value = "#0";
			if (num.HasValue)
			{
				value = "#" + num.Value;
			}
			else
			{
				num = 0;
			}
			AddChild("@main.Input.ZINTYPE", num.Value);
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMZieglerna.MMZieglerna_React_Add";
			e.LegacyFlags = 0;
			e.HelpId = 86;
			e.HelpFile = "polyfrms.hlp";
			e.ShowPrompts = false;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Add_Reaction;
			e.CompleteDataPaths = new string[1] { "@main.CC Nodes.REAC1.@INDEX" };
			DisplayFormEventArgs e2 = e;
			e2.Parameters.Add("CURRXN", value);
			e2.Parameters.Add("INDEX", value);
			DisplayForm(e2);
		}

