		protected override void OnUpdateData()
		{
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.ZINTYPE", "child_ids"));
			int num = 0;
			if (array != null)
			{
				string[] array2 = array;
				foreach (string rownum in array2)
				{
					HiddenReacts(rownum, num);
					num++;
				}
			}
			base.OnUpdateData();
		}

		private void HiddenReacts(string rownum, int rowIndex)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.INCRX." + rownum, "value"));
			if (text == "YES")
			{
				GrayedOutRowIds.Remove(rowIndex);
			}
			else if (text == "NO" && !GrayedOutRowIds.Contains(rowIndex))
			{
				GrayedOutRowIds.Add(rowIndex);
			}
		}
	}
