		private void cmdNew_CommandExecute(object parameter)
		{
			int num = 999;
			int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.COEF", "child_count"));
			if (num2.HasValue && num2.HasValue && num2.Value >= num)
			{
				ShowMMMessageBox(new ShowMMMessageBoxEventArgs
				{
					Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message52, num.ToString()),
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_New_Reaction,
					MsgBoxButton = 0,
					MsgBoxImage = 0,
					DialogResult = 1
				});
				return;
			}
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
			string value = (num2.Value + 1).ToString();
			if (array != null)
			{
				List<string> list = new List<string>(array);
				for (int i = 1; i <= num2.Value; i++)
				{
					if (!list.Contains(i.ToString()))
					{
						value = i.ToString();
						break;
					}
				}
			}
			AddChild("@main.Input.COEF", num2.Value);
			ExpandDataPathAndSet("@main.Input.COEF.#" + num2.Value, "id", value);
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMUserdef.MMUserdef_Input_Edit";
			e.LegacyFlags = 0;
			e.HelpId = 164;
			e.HelpFile = "Reaction.hlp";
			e.ShowPrompts = true;
			e.ResizeMode = ResizeMode.CanResize;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Reaction;
			e.CompleteDataPaths = new string[1] { "STOI" };
			e.Parameters.Add("RXNNO", value);
			DisplayForm(e);
		}

