			{
				IsReadOnly = true,
				Parameter = "ReactantsText"
			});

			public static readonly CxvPropertyDeclaration inner_Property = CxvPropertyDeclaration.Register("inner", typeof(grdReacList_GridData_ItemTemplate), new CxvVectorProperty
			{
				ItemType = typeof(grdReacList_GridData_ItemTemplate_inner_ItemTemplate),
				IndexBasis = new CxvChildCountIndexBasis
				{
					DataPath = "@main.Input.RC_SETS1.@Reac",
					UseChildId = true,
					ProxyRow = true,
