			public string ReactionNoText
			{
				get
				{
					string text = (string)ResolveParameter("Reac");
					string text2 = "#" + (int.Parse(text) - 1);
					string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.RXNTYPE." + text2, "value"));
					return text + ") " + text3;
				}
			}

			public object txtReaction_Reaction => GetValue(txtReaction_Reaction_Property);

			public string ReactantsText
			{
				get
				{
					string text = "";
					string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.REACOEF.@Reac", "child_ids"));
					if (array != null)
					{
						string[] array2 = array;
						foreach (string text2 in array2)
						{
							double? num = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.REACOEF.@Reac." + text2, "value"));
							if (!num.HasValue)
							{
								continue;
							}
							num = Math.Abs(num.Value);
							if (num == 1.0)
							{
								text += text2;
								text += " + ";
								continue;
							}
							for (int j = 0; j < (int)num.Value; j++)
							{
								text += text2;
								text += " + ";
							}
						}
						if (text.Length > 3 && text.Substring(text.Length - 3).Equals(" + "))
						{
							text = text.Remove(text.Length - 3);
						}
					}
					text += " -> ";
					array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.PROCOEF.@Reac", "child_ids"));
					if (array != null)
					{
						string[] array2 = array;
						foreach (string text3 in array2)
						{
							double? num2 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.PROCOEF.@Reac." + text3, "value"));
							if (!num2.HasValue)
							{
								continue;
							}
							num2 = Math.Abs(num2.Value);
							if (num2 == 1.0)
							{
								text += text3;
								text += " + ";
								continue;
							}
							for (int k = 0; k < (int)num2.Value; k++)
							{
								text += text3;
								text += " + ";
							}
						}
						if (text.Length > 3 && text.Substring(text.Length - 3).Equals(" + "))
						{
							text = text.Remove(text.Length - 3);
						}
					}
					return text;
				}
			}

			public object Reactants_var => GetValue(Reactants_var_Property);

			public object inner => GetValue(inner_Property);
		}

