		private void cmdDelete_CommandExecute(object parameter)
		{
			List<string> children = new List<string> { parameter as string };
			DeleteChildren(new string[1] { "@main.Input.COEF" }, children);
		}

		private void DeleteChildren(IEnumerable<string> parentPath, IEnumerable<string> children)
		{
			string msgBox_Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message48;
			bool flag = false;
			List<string> list = new List<string>();
			for (int i = 0; i < children.Count(); i++)
			{
				if (flag)
				{
					list.Add(children.ElementAt(i));
					continue;
				}
				msgBox_Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message48, children.ElementAt(i));
				ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					Message = msgBox_Message,
					MsgBoxButton = ((children.Count() == 1) ? 1 : 13),
					MsgBoxImage = 32,
					DialogResult = 1
				};
				ShowMMMessageBox(e);
				if (children.Count() == 1)
				{
					if (e.DialogResult == 1)
					{
						list.Add(children.ElementAt(i));
					}
					continue;
				}
				flag = e.DialogResult == 14;
				bool num = e.DialogResult == 15;
				if (e.DialogResult == 6 || flag)
				{
					list.Add(children.ElementAt(i));
				}
				if (num)
				{
					break;
				}
				if (e.DialogResult == 2)
				{
					list.Clear();
					break;
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			foreach (string item in list)
			{
				foreach (string item2 in parentPath)
				{
					InvokeAction(item2, "DeleteChild", true, item);
				}
			}
			UpdateDisplay();
			UpdateAll();
		}

		private void cmdRxnAdd_CommandExecute(object parameter)
		{
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMStepgrow.MMStepgrow_React_Add";
			e.LegacyFlags = 0;
			e.HelpId = 75;
			e.HelpFile = "polyfrms.hlp";
			e.ShowPrompts = true;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Stoichiometry;
			e.CompleteDataPaths = new string[4] { "REAC1", "RXNRSC", "RXNPSC", "KIN" };
			e.ResizeMode = ResizeMode.CanResize;
			DisplayFormEventArgs e2 = e;
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.COEF", "child_count"));
			if (!num.HasValue)
			{
				num = 0;
			}
			AddChild("@main.Input.COEF", num.Value);
			int num2 = 0;
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
			if (array != null)
			{
				string[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					if (int.TryParse(array2[i], out var result) && result > num2)
					{
						num2 = result;
					}
				}
			}
			ExpandDataPathAndSet("@main.Input.COEF.#" + num, "id", num2 + 1);
			e2.Parameters.Add("RXNNO", num2 + 1);
			DisplayForm(e2);
		}

		private void cmdRxnEdit_CommandExecute(object parameter)
		{
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMStepgrow.MMStepgrow_React_Add";
			e.LegacyFlags = 0;
			e.HelpId = 76;
			e.HelpFile = "polyfrms.hlp";
