			e.CompleteDataPaths = new string[4] { "REAC1", "RXNRSC", "RXNPSC", "KIN" };
			DisplayFormEventArgs e2 = e;
			string value = "1";
			if (_selectedRowIndexes != null && _selectedRowIndexes.Count > 0)
			{
				int index = _selectedRowIndexes[0];
				value = ((grdReacList_GridData as IList)[index] as grdReacList_GridData_ItemTemplate).ResolveViewPropertyPath("txtDisUrno_Reacno.Value") as string;
			}
