		protected override void OnUpdateData()
		{
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
			if (array != null)
			{
				int num = 0;
				string[] array2 = array;
				foreach (string rownum in array2)
				{
					HiddenReacts(rownum, num);
					num++;
				}
			}
			base.OnUpdateData();
		}

		private void HiddenReacts(string rownum, int rowIndex)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.INURXP." + rownum, "value"));
			ExpandDataPathAndSet("@main.Input.INURXA." + rownum, "value", text);
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.INURX." + rownum, "child_ids"));
			if (array != null)
			{
				string[] array2 = array;
				foreach (string text2 in array2)
				{
					ExpandDataPathAndSet("@main.Input.INURX." + rownum + "." + text2, "value", text);
				}
			}
			string[] array3 = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.INURX1." + rownum, "child_ids"));
			if (array3 != null)
			{
				string[] array2 = array3;
				foreach (string text3 in array2)
				{
					ExpandDataPathAndSet("@main.Input.INURX1." + rownum + "." + text3, "value", text);
				}
			}
			if (text == "YES")
			{
				GrayedOutRowIds.Remove(rowIndex);
			}
			else if (text == "NO" && !GrayedOutRowIds.Contains(rowIndex))
			{
				GrayedOutRowIds.Add(rowIndex);
			}
		}
	}
