		private void ChangeGridVisiblity()
		{
			int? num = CxsConverter.ValueToInt32(((CxvVariableData)spnNint_NINT).Value);
			int? num2 = CxsConverter.ValueToInt32(((CxvVariableData)spnNreal_NREAL).Value);
			string value = CxsConverter.ValueToString(ResolveViewPropertyPath("lbtuKname_Var1.Value", null));
			if (!num.HasValue && !num2.HasValue && !string.IsNullOrEmpty(value))
			{
				num = 1;
				num2 = 1;
			}
			CxvVectorPropertyData cxvVectorPropertyData = grdParamArray_Int_GridData as CxvVectorPropertyData;
			CxvVectorPropertyData cxvVectorPropertyData2 = grdParamArray_Real_GridData as CxvVectorPropertyData;
			if (num.HasValue && num2.HasValue)
			{
				if (num.Value >= num2.Value)
				{
					ResolveUpdateParameter("ParamArrayIntVisible", "1");
					ResolveUpdateParameter("ParamArrayRealVisible", "0");
					for (int i = 0; i < num2.Value; i++)
					{
						if (i < cxvVectorPropertyData.Count && cxvVectorPropertyData[i] is grdParamArray_GridData_ItemTemplate grdParamArray_GridData_ItemTemplate)
						{
							(grdParamArray_GridData_ItemTemplate.txtReal_rvaluelist as CxvVariableData).UnsetReadOnly();
							(grdParamArray_GridData_ItemTemplate.txtReal_rvaluelist as CxvVariableData).IsCalculated = null;
						}
					}
					for (int j = num2.Value; j < num.Value; j++)
					{
						if (j < cxvVectorPropertyData.Count && cxvVectorPropertyData[j] is grdParamArray_GridData_ItemTemplate grdParamArray_GridData_ItemTemplate2)
						{
							(grdParamArray_GridData_ItemTemplate2.txtReal_rvaluelist as CxvVariableData).IsReadOnly = true;
							(grdParamArray_GridData_ItemTemplate2.txtReal_rvaluelist as CxvVariableData).IsCalculated = false;
						}
					}
				}
				else
				{
					ResolveUpdateParameter("ParamArrayIntVisible", "0");
					ResolveUpdateParameter("ParamArrayRealVisible", "1");
					for (int k = 0; k < num.Value; k++)
					{
						if (k < cxvVectorPropertyData2.Count && cxvVectorPropertyData2[k] is grdParamArray_GridData_ItemTemplate grdParamArray_GridData_ItemTemplate3)
						{
							(grdParamArray_GridData_ItemTemplate3.txtInteger_valuelist as CxvVariableData).UnsetReadOnly();
							(grdParamArray_GridData_ItemTemplate3.txtInteger_valuelist as CxvVariableData).IsCalculated = null;
						}
					}
					for (int l = num.Value; l < num2.Value; l++)
					{
						if (l < cxvVectorPropertyData2.Count && cxvVectorPropertyData2[l] is grdParamArray_GridData_ItemTemplate grdParamArray_GridData_ItemTemplate4)
						{
							(grdParamArray_GridData_ItemTemplate4.txtInteger_valuelist as CxvVariableData).IsReadOnly = true;
							(grdParamArray_GridData_ItemTemplate4.txtInteger_valuelist as CxvVariableData).IsCalculated = false;
						}
					}
				}
			}
			if (!num.HasValue && !num2.HasValue)
			{
				ResolveUpdateParameter("ParamArrayIntVisible", "1");
				ResolveUpdateParameter("ParamArrayRealVisible", "0");
			}
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			base.OnSubPropertyDataChanged(pd, subPropertyName);
			if ((pd.Name == "spnNint_NINT" || pd.Name == "spnNreal_NREAL" || pd.Name == "lbtuKname_Var1") && subPropertyName == "Value")
			{
				ChangeGridVisiblity();
			}
		}
	}
