		private void cmdDelete_CommandExecute(object parameter)
		{
			List<string> children = new List<string> { parameter as string };
			DeleteChildren(new string[1] { "@main.Input.COEF" }, children);
		}

		private void DeleteChildren(IEnumerable<string> parentPath, IEnumerable<string> children)
		{
			string msgBox_Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message48;
			bool flag = false;
			List<string> list = new List<string>();
			for (int i = 0; i < children.Count(); i++)
			{
				if (flag)
				{
					list.Add(children.ElementAt(i));
					continue;
				}
				msgBox_Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message49, children.ElementAt(i));
				ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					Message = msgBox_Message,
					MsgBoxButton = ((children.Count() == 1) ? 1 : 13),
					MsgBoxImage = 32,
					DialogResult = 1
				};
				ShowMMMessageBox(e);
				if (children.Count() == 1)
				{
					if (e.DialogResult == 1)
					{
						list.Add(children.ElementAt(i));
					}
					continue;
				}
				flag = e.DialogResult == 14;
				bool num = e.DialogResult == 15;
				if (e.DialogResult == 6 || flag)
				{
					list.Add(children.ElementAt(i));
				}
				if (num)
				{
					break;
				}
				if (e.DialogResult == 2)
				{
					list.Clear();
					break;
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			foreach (string item in list)
			{
				foreach (string item2 in parentPath)
				{
					InvokeAction(item2, "DeleteChild", true, item);
				}
			}
			UpdateDisplay();
			UpdateAll();
		}

		private void cmdRxnAdd_CommandExecute(object parameter)
