		private void cmdKinetic_CommandExecute(object parameter)
		{
			isFirstRunKineticCommand = false;
			ResolveUpdateParameter("PrecipitatingSaltVisible", "1");
			cboRxnIdVar.IsVisible = false;
			int num = 1;
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
			if (array != null && array.Length != 0)
			{
				List<int> list = new List<int>();
				string[] array2 = array;
				foreach (string value in array2)
				{
					list.Add(Convert.ToInt32(value));
				}
				list.Sort();
				int num2 = list[list.Count - 1];
				for (int j = 1; j <= num2 + 1; j++)
				{
					if (!list.Contains(j))
					{
						num = j;
						break;
					}
				}
			}
			ExpandDataPathAndSet("@main.Input.TEXT", "value", num);
		}

		private void cmdSalt_CommandExecute(object parameter)
		{
			ResolveUpdateParameter("PrecipitatingSaltVisible", "0");
			cboRxnIdVar.IsVisible = true;
			ReadOnlyCollection<string> readOnlyCollection = CxsConverter.ValueToOptionsCollection(ExpandDataPathAndGet("@main.Input.SALT_COEF", "child_ids_options"));
			if (readOnlyCollection == null)
			{
				return;
			}
			ObservableCollection<string> observableCollection = new ObservableCollection<string>();
			foreach (string item in readOnlyCollection)
			{
				ReadOnlyCollection<string> readOnlyCollection2 = CxsConverter.ValueToOptionsCollection(ExpandDataPathAndGet("@main.Input.SALT_COEF", "child_ids"));
				bool flag = false;
				if (readOnlyCollection2 != null)
				{
					foreach (string item2 in readOnlyCollection2)
					{
						if (item2 == item)
						{
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					observableCollection.Add(item);
				}
			}
			cboRxnIdVar.ValueOptions = observableCollection;
		}

		private void cmdOK_CommandExecute(object parameter)
		{
			if (!(base.View is MMReactdist_Input_New mMReactdist_Input_New))
			{
				return;
			}
			if (mMReactdist_Input_New.optEquilibrium.IsChecked == true)
			{
				string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.TEXT", "value"));
				if (string.IsNullOrEmpty(text))
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message42,
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Reaction_Number,
						MsgBoxButton = MessageBoxButton.OK,
						MsgBoxImage = MessageBoxImage.Exclamation
					});
					return;
				}
				int num = Convert.ToInt32(text);
				if (num < 1 || num > 999)
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message43,
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Reaction_Number,
						MsgBoxButton = MessageBoxButton.OK
					});
					return;
				}
				int location = 0;
				string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
				bool flag = false;
				if (array != null)
				{
					location = array.Length;
					string[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						if (array2[i] == text)
						{
							flag = true;
							break;
						}
					}
				}
				if (flag)
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message44, text),
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Reaction_Number,
						MsgBoxButton = MessageBoxButton.OK
					});
					return;
				}
				AddChild("@main.Input.COEF", location);
				ExpandDataPathAndSet("@main.Input.COEF.#" + location, "id", text);
				DisplayFormEventArgs e = new DisplayFormEventArgs();
				e.FormProgId = "MMReactdist.MMReactdist_Input_Edit";
				e.LegacyFlags = 32;
				e.HelpId = 207;
				e.HelpFile = "Reaction.hlp";
				e.ResizeMode = ResizeMode.CanResize;
				e.ShowPrompts = true;
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Reaction;
				e.CompleteDataPaths = new string[1] { "STOI" };
				DisplayFormEventArgs e2 = e;
				e2.Parameters.Add("RXNNO", text);
				DisplayForm(e2);
				CloseForm();
			}
			else if (mMReactdist_Input_New.optSalt.IsChecked == true)
			{
				if (cboRxnIdVar.Value == null || cboRxnIdVar.Value.ToString() == "")
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message53,
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Salt_ID,
						MsgBoxButton = MessageBoxButton.OK,
						MsgBoxImage = MessageBoxImage.Exclamation
					});
					return;
				}
				string text2 = mMReactdist_Input_New.cboRxnId.Value.ToString();
				int location2 = 0;
				string[] array3 = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.SALT_COEF", "child_ids"));
				bool flag2 = false;
				if (array3 != null)
				{
					location2 = array3.Length;
					string[] array2 = array3;
					for (int i = 0; i < array2.Length; i++)
					{
						if (array2[i] == text2)
						{
							flag2 = true;
							break;
						}
					}
				}
				if (!flag2)
				{
					AddChild("@main.Input.SALT_COEF", location2);
					ExpandDataPathAndSet("@main.Input.SALT_COEF.#" + location2, "id", text2);
				}
				int num2 = 0;
				int num3 = 0;
				ReadOnlyCollection<string> readOnlyCollection = CxsConverter.ValueToOptionsCollection(ExpandDataPathAndGet("@main.Input.SALT_COEF", "child_ids_options"));
				if (readOnlyCollection != null)
				{
					foreach (string item in readOnlyCollection)
					{
						if (item == text2)
						{
							num3 = num2;
							break;
						}
						num2++;
					}
				}
				DisplayFormEventArgs e = new DisplayFormEventArgs();
				e.FormProgId = "MMReactdist.MMReactdist_Input_EditSalt";
				e.LegacyFlags = 32;
				e.HelpId = 257;
				e.HelpFile = "Reaction.hlp";
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Salt;
				e.ResizeMode = ResizeMode.CanResize;
				e.ShowPrompts = true;
				e.CompleteDataPaths = new string[1] { "SALT1" };
				DisplayFormEventArgs e3 = e;
				e3.Parameters.Add("RXNNO", num3);
				DisplayForm(e3);
				CloseForm();
			}
			isFirstRunKineticCommand = true;
		}

		private void cmdClose_CommandExecute(object parameter)
		{
			isFirstRunKineticCommand = true;
			CloseForm();
		}

		protected override void OnUpdateData()
		{
			base.OnUpdateData();
			if (base.IsInitialUpdate && isFirstRunKineticCommand)
			{
				cmdKinetic_Command.Execute(null);
			}
		}
	}
