			base.OnUpdateData();
		}

		private void dataWatch_PropertyDependencyChanged(object sender, EventArgs e)
		{
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.S_KBASIS", "child_count"));
			if (num.HasValue && num.Value > oldCount)
			{
				_isSaltIdsChanged = true;
