		private void cmdNew_CommandExecute(object parameter)
		{
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMReactdist.MMReactdist_Input_New";
			e.LegacyFlags = 0;
			e.HelpId = 198;
			e.HelpFile = "Reaction.hlp";
			e.ShowPrompts = true;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Select_Reaction_Type;
			DisplayForm(e);
		}

		private void cmdEdit_CommandExecute(object parameter)
		{
			int position = SelectedRowIndexes[0];
			string id = GetId(position);
			string rxnType = GetRxnType(position);
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.LegacyFlags = 0;
			e.HelpId = 207;
			e.HelpFile = "Reaction.hlp";
			e.ShowPrompts = true;
			e.ResizeMode = ResizeMode.CanResize;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Reaction;
			e.CompleteDataPaths = new string[1] { "STOI" };
			switch (rxnType)
			{
			case "EQUIL":
				e.FormProgId = "MMReactdist.MMReactdist_Input_Edit";
				break;
			case "Salt":
				e.FormProgId = "MMReactdist.MMReactdist_Input_EditSalt";
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Salt;
				e.CompleteDataPaths = new string[1] { "SALT1" };
				e.HelpId = 257;
				break;
			case "KINETIC":
				e.FormProgId = "MMReactdist.MMReactdist_Input_Edit";
				break;
			case "CONV":
				e.FormProgId = "MMReactdist.MMReactdist_Input_Edit";
				break;
			default:
				e.FormProgId = "MMReactdist.MMReactdist_Input_Edit";
				break;
			}
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Reaction;
			e.Parameters.Add("RXNNO", id);
			DisplayForm(e);
		}

		private void cmdCopy_CommandExecute(object parameter)
		{
			string mainPath = CxsConverter.ValueToString(ResolveParameter("main", null));
			this.CopyObjectRows(mainPath, "REACTDIST", SelectedRowIndexes);
			OnCanPasteChanged();
		}

		private void OnCanPasteChanged()
		{
			if (this.CanPasteChanged != null)
			{
				this.CanPasteChanged(this, EventArgs.Empty);
			}
			OnPropertyChanged("CanPaste");
		}

		private void cmdPaste_CommandExecute(object parameter)
		{
			if (!CanPaste)
			{
				OnCanPasteChanged();
				return;
			}
			string mainPath = CxsConverter.ValueToString(ResolveParameter("main", null));
			if (SelectedRowIndexes.Count == 1)
			{
				this.PasteObjectRows(mainPath, "REACTDIST", SelectedRowIndexes[0]);
			}
			else
			{
				this.PasteObjectRows(mainPath, "REACTDIST");
			}
		}

		private void cmdDelete_CommandExecute(object parameter)
		{
			List<int> list = new List<int>();
			string text = parameter as string;
			if (!string.IsNullOrEmpty(text))
			{
				int num = 0;
				foreach (object item in grdStoic_GridData as IList)
				{
					if ((item as grdStoic_GridData_ItemTemplate).GetId() == text)
					{
						list.Add(num);
						break;
					}
					num++;
				}
			}
			else
			{
				foreach (int selectedRowIndex in SelectedRowIndexes)
				{
					if (list.Count <= 0)
					{
						list.Add(selectedRowIndex);
						continue;
					}
					for (int i = 0; i < list.Count; i++)
					{
						if (selectedRowIndex > list[i])
						{
							list.Insert(i, selectedRowIndex);
							break;
						}
						if (i == list.Count - 1)
						{
							list.Add(selectedRowIndex);
							break;
						}
					}
				}
			}
			DeleteChildren(list);
		}

		private void DeleteChildren(List<int> selectedPosList)
		{
			IEnumerable<string> source = selectedPosList.Select((int index) => GetId(index));
			string msgBox_Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message48;
			bool flag = false;
			List<string> list = new List<string>();
			for (int num = 0; num < source.Count(); num++)
			{
				if (flag)
				{
					list.Add(source.ElementAt(num));
					continue;
				}
				msgBox_Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message49, source.ElementAt(num));
				ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					Message = msgBox_Message,
					MsgBoxButton = ((source.Count() == 1) ? 1 : 13),
					MsgBoxImage = 32,
					DialogResult = 1
				};
				ShowMMMessageBox(e);
				if (source.Count() == 1)
				{
					if (e.DialogResult == 1)
					{
						list.Add(source.ElementAt(num));
					}
					continue;
				}
				flag = e.DialogResult == 14;
				bool num2 = e.DialogResult == 15;
				if (e.DialogResult == 6 || flag)
				{
					list.Add(source.ElementAt(num));
				}
				if (num2)
				{
					break;
				}
				if (e.DialogResult == 2)
				{
					list.Clear();
					break;
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			Collection<string> collection = new Collection<string>();
			Collection<string> collection2 = new Collection<string>();
			for (int num3 = 0; num3 < selectedPosList.Count(); num3++)
			{
				int position = selectedPosList[num3];
				string id = GetId(position);
				string rxnType = GetRxnType(position);
				if (rxnType.Equals(ApwnResources.MMReactdist_Input_MMFHeader1, StringComparison.InvariantCultureIgnoreCase))
				{
					collection.Add(id);
				}
				else if (rxnType.Equals(ApwnResources.MMReactdist_Input_Equil, StringComparison.InvariantCultureIgnoreCase))
				{
					collection.Add(id);
				}
				else if (rxnType.Equals(ApwnResources.MMReactdist_Input_Conv, StringComparison.InvariantCultureIgnoreCase))
				{
					collection.Add(id);
				}
				else if (rxnType.Equals(ApwnResources.MMReactdist_Input_MMFHeader4, StringComparison.InvariantCultureIgnoreCase))
				{
					collection2.Add(id);
				}
			}
			foreach (string item in collection)
			{
				InvokeAction("@main.Input.COEF", "DeleteChild", true, item);
			}
			foreach (string item2 in collection2)
			{
				InvokeAction("@main.Input.SALT_COEF", "DeleteChild", true, item2);
			}
			UpdateDisplay();
			UpdateAll();
		}

