		private IEnumerable<string> GetSelectedIds()
		{
			IList gridData = grdStoic_GridData as IList;
			foreach (int selectedRowIndex in SelectedRowIndexes)
			{
				grdStoic_GridData_ItemTemplate grdStoic_GridData_ItemTemplate = gridData[selectedRowIndex] as grdStoic_GridData_ItemTemplate;
				yield return grdStoic_GridData_ItemTemplate.GetId();
			}
		}

		private string GetId(int position)
		{
			return ((grdStoic_GridData as IList)[position] as grdStoic_GridData_ItemTemplate).GetId();
		}

		private string GetRxnType(int position)
		{
			return ((grdStoic_GridData as IList)[position] as grdStoic_GridData_ItemTemplate).GetRxnType();
		}

