		public ICommand DeleteRowCommand { get; } = new DelegateCommand<object>(delegate
		{
		}, (object _) => false);

		private void GenRxn_CommandExecute(object parameter)
		{
			int valueOrDefault = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.REACTYPE", "child_count")).GetValueOrDefault();
			if (valueOrDefault > 0)
			{
				ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MMZieglerna_MSGBox_Message,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					MsgBoxButton = MessageBoxButton.OKCancel,
					MsgBoxImage = MessageBoxImage.Question
				};
				ShowMessageBox(e);
				if (e.DialogResult == MessageBoxResult.Cancel)
				{
					return;
				}
			}
			for (int i = 1; i <= valueOrDefault; i++)
			{
				InvokeAction("@main.Input.REACTYPE", "DeleteChild", false, i.ToString());
			}
			List<string> list = new List<string>();
			list.Add(CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.R_SEG", "value")));
			if (list.Count == 0)
			{
				return;
			}
			int num = 0;
			int num2 = 0;
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.REACTYPE1", "option_list"));
			foreach (string value in array)
			{
				num++;
				if (CxsConverter.ValueToString(ExpandDataPathAndGet($"@main.Input.INCRX.{num}", "value")) == "NO")
				{
					continue;
				}
				for (int k = 0; k < list.Count(); k++)
