		private void cmdNew_CommandExecute(object parameter)
		{
			int num = 999;
			int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.REACTYPE", "child_count"));
			if (num2.HasValue && num2.HasValue && num2 >= num)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message52, num.ToString()),
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_New_Reaction,
					MsgBoxButton = MessageBoxButton.OK
				});
				return;
			}
			int num3 = num2.Value + 1;
			AddChild("@main.Input.REACTYPE", num3);
			string value = "1";
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.REACTYPE", "child_ids"));
			if (array != null && array.Length != 0)
			{
				value = (array.Length + 1).ToString();
				List<string> list = new List<string>(array);
				for (int i = 1; i <= array.Length; i++)
				{
					if (!list.Contains(i.ToString()))
					{
						value = i.ToString();
						break;
					}
				}
			}
			ExpandDataPathAndSet("@main.Input.REACTYPE.#" + num2.Value, "id", value);
			DisplayFormEventArgs e = new DisplayFormEventArgs
			{
				FormProgId = "MMPowerlaw.MMPowerlaw_Input_Edit",
				LegacyFlags = 0,
				HelpId = 69,
				HelpFile = "Reaction.hlp",
				ShowPrompts = true,
				ResizeMode = ResizeMode.CanResize,
				ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Reaction
			};
			e.Parameters.Add("reactno", num3);
			DisplayForm(e);
		}

