		private void cmdDelete_CommandExecute(object parameter)
		{
			if (parameter != null)
			{
				List<string> children = new List<string> { parameter as string };
				DeleteChildren("@main.Input.REACTYPE", children);
			}
			else
			{
				if (SelectedRowIndexes == null || SelectedRowIndexes.Count <= 0)
				{
					return;
				}
				CxvVectorPropertyData data = grdStoic_GridData as CxvVectorPropertyData;
				if (data != null)
				{
					IEnumerable<string> children2 = from row in SelectedRowIndexes
						orderby row
						select (data[row] as grdStoic_GridData_ItemTemplate).GetId();
					DeleteChildren("@main.Input.REACTYPE", children2);
				}
			}
		}

