		private void cmdNew_CommandExecute(object parameter)
		{
			if (CheckDuplicate())
			{
				DeleteNewChild();
			}
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.IONTYPE", "child_count"));
			string value = "#0";
			if (num.HasValue)
			{
				value = "#" + num.Value;
			}
			else
			{
				num = 0;
			}
			AddChild("@main.Input.IONTYPE", num.Value);
			ResolveUpdateParameter("CURRXN", value);
		}

		private void cmdAClose_CommandExecute(object parameter)
		{
			if (CheckDuplicate())
			{
				DeleteNewChild();
			}
			CloseForm();
		}

		private void cmdACancel_CommandExecute(object parameter)
		{
			DeleteNewChild();
			CloseForm();
		}

