		private bool CheckDuplicate()
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.IONTYPE.@CURRXN", "value"));
			string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID1.@CURRXN", "value"));
			string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID2.@CURRXN", "value"));
			string text4 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID3.@CURRXN", "value"));
			string text5 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1.@CURRXN", "value"));
			string text6 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2.@CURRXN", "value"));
			string dataPath = "@main.Input.IONTYPE";
			string text7 = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(dataPath, "child_ids"));
			if (array != null)
			{
				List<string> list = new List<string>(array);
				for (int i = 0; i < list.Count; i++)
				{
					if (text7 != list[i])
					{
						string text8 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.IONTYPE." + list[i], "value"));
						string text9 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID1." + list[i], "value"));
						string text10 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID2." + list[i], "value"));
						string text11 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SITE_ID3." + list[i], "value"));
						string text12 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1." + list[i], "value"));
						string text13 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2." + list[i], "value"));
						if (text == text8 && text2 == text9 && text3 == text10 && text4 == text11 && text5 == text12 && text6 == text13)
						{
							ShowMessageBoxEventArgs args = new ShowMessageBoxEventArgs
							{
								Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message50,
								Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Caption_Add_Reaction,
								MsgBoxButton = MessageBoxButton.OK
							};
							ShowMessageBox(args);
							return true;
						}
					}
				}
			}
			return false;
		}

		private void DeleteNewChild()
		{
			string text = "@main.Input.IONTYPE";
			string text2 = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(text, "child_ids"));
			if (array == null)
			{
				return;
			}
			List<string> list = new List<string>(array);
			for (int i = 0; i < list.Count; i++)
			{
				if (text2 == list[i])
				{
					DeleteChild(text, i);
				}
			}
		}

