	internal class ActivityChildCountIndexBasisData : CxvChildCountIndexBasisData
	{
		public ActivityChildCountIndexBasisData(ActivityChildCountIndexBasis indexBasis, ICxvViewDataContainer dataContainer)
			: base(indexBasis, dataContainer)
		{
		}

		public override void RemoveAt(int index)
		{
			if (!(base.DataContainer is MMViewModel mMViewModel))
			{
				return;
			}
			try
			{
				string text = CxsPath.ParentPath(mMViewModel.ExpandDataPath(base.IndexBasis.DataPath));
				string[] array = CxsConverter.ValueToStringArray(mMViewModel.ExpandDataPathAndGet(text, "child_ids"));
				if (array != null)
				{
					string[] array2 = array;
					foreach (string id in array2)
					{
						string path = CxsPath.CombinePathAndId(text, id);
						mMViewModel.ResolvedCxsProvider.InvokeAction(path, "DeleteChild", true, index);
					}
				}
			}
			catch (CxsException)
			{
			}
		}

		public override bool AllowRemoveAt(int index)
		{
			if (index > Count - 1)
			{
				return false;
			}
			return true;
		}
	}
