			{
				if (cxvAdvCollectionPropertyData.SelectedItem == AspenTech.AspenPlus.Localization.Properties.Resources.MMGENERAL_Input_Drivin_ViewModel__CxvAdvCollectionItem_Display_Forward || num == 1)
				{
					ResolveUpdateParameter("exponent", "EXPONENT");
					ResolveUpdateParameter("exponent1", "EXPONENT1");
					ResolveUpdateParameter("df1", "DF1_A");
					ResolveUpdateParameter("df2", "DF1_B");
					ResolveUpdateParameter("df3", "DF1_C");
					ResolveUpdateParameter("df4", "DF1_D");
				}
				if (cxvAdvCollectionPropertyData.SelectedItem == AspenTech.AspenPlus.Localization.Properties.Resources.MMGENERAL_Input_Drivin_ViewModel__CxvAdvCollectionItem_Display_Reverse && num == 0)
				{
					ResolveUpdateParameter("exponent", "EXPON");
					ResolveUpdateParameter("exponent1", "EXPON1");
					ResolveUpdateParameter("df1", "DF2_A");
					ResolveUpdateParameter("df2", "DF2_B");
					ResolveUpdateParameter("df3", "DF2_C");
					ResolveUpdateParameter("df4", "DF2_D");
				}
			}
		}

