		protected override void OnUpdateData()
		{
			if (base.IsInitialUpdate)
			{
				ResolveUpdateParameter("SpeVisible", "1");
				ResolveUpdateParameter("SumVisible", "0");
				bool flag = true;
				bool flag2 = false;
				if (CxsConverter.ValueToString(ExpandDataPathAndGet("@main", "type")).ToUpper() == "USERACM")
				{
					flag = false;
					flag2 = true;
				}
				ResolveUpdateParameter("ReactingPhase0_Visible", flag);
				ResolveUpdateParameter("ReactingPhase1_Visible", flag2);
			}
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.CC Nodes.REVSPC1.@reactnok", "value"));
			if (Advcbo_AdvCollection is CxvAdvCollectionPropertyData cxvAdvCollectionPropertyData)
