				if (cxvAdvCollectionPropertyData.SelectedItem == AspenTech.AspenPlus.Localization.Properties.Resources.MMGENERAL_Input_Drivin_ViewModel__CxvAdvCollectionItem_Display_Forward || num == 1)
				{
					ResolveUpdateParameter("exponent", "EXPONENT");
					ResolveUpdateParameter("exponent1", "EXPONENT1");
					ResolveUpdateParameter("df1", "DF1_A");
					ResolveUpdateParameter("df2", "DF1_B");
					ResolveUpdateParameter("df3", "DF1_C");
					ResolveUpdateParameter("df4", "DF1_D");
				}
				if (cxvAdvCollectionPropertyData.SelectedItem == AspenTech.AspenPlus.Localization.Properties.Resources.MMGENERAL_Input_Drivin_ViewModel__CxvAdvCollectionItem_Display_Reverse && num == 0)
				{
					ResolveUpdateParameter("exponent", "EXPON");
					ResolveUpdateParameter("exponent1", "EXPON1");
					ResolveUpdateParameter("df1", "DF2_A");
					ResolveUpdateParameter("df2", "DF2_B");
					ResolveUpdateParameter("df3", "DF2_C");
					ResolveUpdateParameter("df4", "DF2_D");
				}
				base.OnUpdateData();
			}
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			base.OnSubPropertyDataChanged(pd, subPropertyName);
			if (pd.Name == "strKinet_var3" && subPropertyName == "Value" && strKinet_var3 is CxvParameterPropertyData cxvParameterPropertyData)
			{
				string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
				if (cxvParameterPropertyData.Value == null || array == null)
				{
					ResolveUpdateParameter("reactnok", null);
					return;
				}
				int num = 0;
				string[] array2 = array;
				foreach (string text in array2)
				{
					if (text == cxvParameterPropertyData.Value.ToString())
					{
						ResolveUpdateParameter("reactnok", text);
						break;
					}
					num++;
				}
			}
			if (pd.Name == "Advcbo_AdvCollection" && subPropertyName == "SelectedItem" && Advcbo_AdvCollection is CxvAdvCollectionPropertyData cxvAdvCollectionPropertyData)
			{
				if (cxvAdvCollectionPropertyData.SelectedItem == AspenTech.AspenPlus.Localization.Properties.Resources.MMGENERAL_Input_Drivin_ViewModel__CxvAdvCollectionItem_Display_Forward)
				{
					ResolveUpdateParameter("exponent", "EXPONENT");
					ResolveUpdateParameter("exponent1", "EXPONENT1");
					ResolveUpdateParameter("df1", "DF1_A");
					ResolveUpdateParameter("df2", "DF1_B");
