		private bool CheckDuplicate()
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.FRRTYPE.@CURRXN", "value"));
			string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1.@CURRXN", "value"));
			string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2.@CURRXN", "value"));
			string dataPath = "@main.Input.FRRTYPE";
			string text4 = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(dataPath, "child_ids"));
			if (array != null)
			{
				List<string> list = new List<string>(array);
				for (int i = 0; i < list.Count; i++)
				{
					if (text4 != list[i])
					{
						string text5 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.FRRTYPE." + list[i], "value"));
						string text6 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1." + list[i], "value"));
						string text7 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2." + list[i], "value"));
						if (text == text5 && text2 == text6 && text3 == text7)
						{
							ShowMessageBoxEventArgs args = new ShowMessageBoxEventArgs
							{
								Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message50,
								Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Caption_Add_Reaction,
								MsgBoxButton = MessageBoxButton.OK
							};
							ShowMessageBox(args);
							return true;
						}
					}
				}
			}
			return false;
		}

		private void DeleteNewChild()
		{
			string text = "@main.Input.FRRTYPE";
			string text2 = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(text, "child_ids"));
			if (array == null)
			{
				return;
			}
			List<string> list = new List<string>(array);
			for (int i = 0; i < list.Count; i++)
			{
				if (text2 == list[i])
				{
					DeleteChild(text, i);
				}
			}
		}

