					ExpandDataPathAndSet("@main.Input.QSSA", "value", "NO");
				}
				else if (text == "ALL")
				{
					ExpandDataPathAndSet("@main.Input.QSSA", "value", "YES");
				}
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}
