		private bool CanPrevExecute(object obj)
		{
			if (storParam_var2 is CxvMultiMapPropertyData cxvMultiMapPropertyData && cxvMultiMapPropertyData.Items.Count != 0 && SelectedReaction == cxvMultiMapPropertyData.Items[0])
			{
				return false;
			}
			return true;
		}

		private bool CanNextExecute(object obj)
		{
			if (storParam_var2 is CxvMultiMapPropertyData cxvMultiMapPropertyData && cxvMultiMapPropertyData.Items.Count != 0 && SelectedReaction == cxvMultiMapPropertyData.Items[cxvMultiMapPropertyData.Items.Count - 1])
			{
				return false;
			}
			return true;
		}

		private bool CanGetRate1Execute(object obj)
		{
			if (storParam_var2 is CxvMultiMapPropertyData cxvMultiMapPropertyData && cxvMultiMapPropertyData.Items.Count != 0)
			{
				return SelectedReaction.Contains("INIT-DEC");
			}
			return false;
		}

		private void cmdPrev_CommandExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			if (!string.IsNullOrEmpty(text))
			{
				int num = int.Parse(text.Substring(1));
				if (num != 0)
				{
					ResolveUpdateParameter("CURRXN", "#" + (num - 1));
					OnUpdateData();
				}
			}
		}

		private void cmdNext_CommandExecute(object parameter)
		{
			int num = int.Parse(CxsConverter.ValueToString(ResolveParameter("CURRXN")).Substring(1));
			int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.FRRTYPE", "child_count"));
			if (num2.HasValue && num2.HasValue && num < num2.Value - 1)
			{
				ResolveUpdateParameter("CURRXN", "#" + (num + 1));
				OnUpdateData();
			}
		}

		private void cmdEClose_CommandExecute(object parameter)
		{
			Unload();
		}

		private void cmdGetRate1_CommandExecute(object parameter)
		{
			CxvMultiMapPropertyData cxvMultiMapPropertyData = storParam_var2 as CxvMultiMapPropertyData;
			int num = -1;
			while (num < cxvMultiMapPropertyData.Items.Count)
			{
				num++;
				if (SelectedReaction == cxvMultiMapPropertyData.Items[num])
				{
					getRateConst1(num);
					break;
				}
			}
		}

		public void getRateConst1(int indx)
		{
			object obj = ExpandDataPathAndGet("@main.Input.FRRTYPE.#" + indx, "value");
			if (obj == null || string.IsNullOrEmpty(obj.ToString()) || obj.ToString() != "INIT-DEC")
			{
				return;
			}
			double? num = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.FRPRE_EXP.#" + indx, "value"));
			double? num2 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.FRACT_ENERGY.#" + indx, "value"));
			double? num3 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.REF_TEMP.#" + indx, "value"));
			if ((num.HasValue && num != 0.0) || (num2.HasValue && num2 != 0.0) || (num3.HasValue && num3 != 1E+35))
			{
				ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
				{
					Title = GetProductI18nName(),
					MsgBoxButton = MessageBoxButton.YesNoCancel
				};
				e.Message = ApwnResources.MMFreerad_GetRate_dBank;
				ShowMessageBox(e);
				if (e.DialogResult == MessageBoxResult.Yes)
				{
					ExpandDataPathAndSet("@main.Input.GETRATE.#" + indx, "value", "0", 2);
				}
				else if (e.DialogResult == MessageBoxResult.No)
				{
					ExpandDataPathAndSet("@main.Input.GETRATE.#" + indx, "value", "0", 1);
				}
			}
			else
			{
				ExpandDataPathAndSet("@main.Input.GETRATE.#" + indx, "value", "0", 2);
			}
		}

		protected override void OnUpdateData()
		{
			if (base.IsInitialUpdate)
			{
				storParam_FillRxnString();
				PolyRedoLabels();
			}
			SelectedReaction = storParam_GenerateRxnString(CxsConverter.ValueToString(ResolveParameter("CURRXN")));
			base.OnUpdateData();
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			if (propertyName == "SelectedReaction")
			{
				string selectedReaction = _selectedReaction;
				try
				{
					if (!string.IsNullOrEmpty(selectedReaction) && selectedReaction.IndexOf(')') > 0)
					{
						string value = "#" + (int.Parse(selectedReaction.Substring(0, selectedReaction.IndexOf(')'))) - 1);
						ResolveUpdateParameter("CURRXN", value);
					}
				}
				catch
				{
				}
				PolyRedoLabels();
			}
			base.OnPropertyChanged(propertyName);
		}

