		private void storParam_FillRxnString()
		{
			CxvMultiMapProperty cxvMultiMapProperty = storParam_var2_Property.Metadata as CxvMultiMapProperty;
			if (cxvMultiMapProperty.Options.Count > 0)
			{
				cxvMultiMapProperty.Options.Clear();
			}
			string dataPath = "@main.Input.FRRTYPE";
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(dataPath, "child_ids"));
			if (array != null)
			{
				for (int i = 0; i < array.Length; i++)
				{
					CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.FRRTYPE." + array[i], "value"));
					CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID1." + array[i], "value"));
					CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.CID2." + array[i], "value"));
					cxvMultiMapProperty.Options.Add(new CxvMultiMapOption
					{
						Display = storParam_GenerateRxnString(array[i], i),
						DisplayResourceKey = "MMFreerad_React_Param_ViewModel__CxvMultiMapOption_Display_" + i,
						Value = "cbo_MultiMapOption_" + array[i]
					});
				}
			}
		}

