		private void cmdHide_CommandExecute(object parameter)
		{
			if (_selectedRowIndexes == null || _selectedRowIndexes.Count == 0)
			{
				return;
			}
			foreach (int selectedRowIndex in _selectedRowIndexes)
			{
				string text = CxsConverter.ValueToString(((grdReacList_GridData as IList)[selectedRowIndex] as grdReacList_GridData_ItemTemplate).ResolveParameter("Reac"));
				string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.INCRX." + text, "value"));
				if (text2 == "YES")
				{
					ExpandDataPathAndSet("@main.Input.INCRX." + text, "value", "NO");
				}
				else if (text2 == "NO")
				{
					ExpandDataPathAndSet("@main.Input.INCRX." + text, "value", "YES");
				}
				HiddenReacts(text, selectedRowIndex);
			}
		}

		private void HiddenReacts(string rownum, int rowIndex)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.INCRX." + rownum, "value"));
			if (text == "YES")
			{
				GrayedOutRowIds.Remove(rowIndex);
			}
			else if (text == "NO" && !GrayedOutRowIds.Contains(rowIndex))
			{
				GrayedOutRowIds.Add(rowIndex);
			}
		}

		private void cmdDelete_CommandExecute(object parameter)
		{
			if (parameter != null)
			{
				List<string> list = new List<string>();
				list.Add((CxsConverter.ValueToInt32(parameter).Value - 1).ToString());
				DeleteChildrenByRowIndex("@main.Input.FRRTYPE", list, silently: false, "reaction");
			}
			else
			{
				if (_selectedRowIndexes == null || _selectedRowIndexes.Count <= 0)
				{
					return;
				}
				List<int> list2 = new List<int>();
				foreach (int selectedRowIndex in _selectedRowIndexes)
				{
					grdReacList_GridData_ItemTemplate container = (grdReacList_GridData as IList)[selectedRowIndex] as grdReacList_GridData_ItemTemplate;
					list2.Add(CxsConverter.ValueToInt32(container.ResolveViewPropertyPath("txtRowNo_RowNo.Value")).Value - 1);
				}
				IEnumerable<string> source = list2.OrderByDescending((int rowNum) => rowNum).Select(delegate(int rowNum)
				{
					int num = rowNum;
					return num.ToString();
				});
				DeleteChildrenByRowIndex("@main.Input.FRRTYPE", source.ToList(), silently: false, "reaction");
			}
		}

		private void cmdRxnAdd_CommandExecute(object parameter)
		{
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.FRRTYPE", "child_count"));
			string value = "#0";
			if (num.HasValue)
			{
				value = "#" + num.Value;
			}
			else
			{
				num = 0;
			}
			AddChild("@main.Input.FRRTYPE", num.Value);
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMFreerad.MMFreerad_React_Add";
			e.LegacyFlags = 0;
			e.HelpId = 50;
			e.HelpFile = "polyfrms.hlp";
			e.ShowPrompts = false;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Caption_Add_Reaction;
			e.CompleteDataPaths = new string[1] { "@main.CC Nodes.REAC1.@INDEX" };
			DisplayFormEventArgs e2 = e;
			e2.Parameters.Add("CURRXN", value);
			e2.Parameters.Add("INDEX", value);
			DisplayForm(e2);
		}

