		protected override void OnUpdateData()
		{
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.FRRTYPE", "child_ids"));
			int num = 0;
			if (array != null)
			{
				string[] array2 = array;
