		public ICommand cmdGetRate_Command
		{
			get
			{
				if (_cmdGetRate_Command == null)
				{
					_cmdGetRate_Command = new CxvDelegateCommand<object>(cmdGetRate_CommandExecute);
				}
				return _cmdGetRate_Command;
			}
