		private void cmdGetRate_CommandExecute(object parameter)
		{
			getRateConst();
		}

		public void getRateConst()
		{
			int num = 0;
			int num2 = 0;
			ArrayList arrayList = new ArrayList();
			while (true)
			{
				object obj = ExpandDataPathAndGet("@main.Input.FRRTYPE.#" + num, "value");
				if (obj == null || string.IsNullOrEmpty(obj.ToString()))
				{
					break;
				}
				if (obj.ToString() == "INIT-DEC")
				{
					arrayList.Add(num);
					num2++;
				}
				num++;
			}
			if (num2 == 0)
			{
				return;
			}
			foreach (int item in arrayList)
			{
				int num3 = item + 1;
				double? num4 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.FRPRE_EXP.#" + item, "value"));
				double? num5 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.FRACT_ENERGY.#" + item, "value"));
				double? num6 = CxsConverter.ValueToDouble(ExpandDataPathAndGet("@main.Input.REF_TEMP.#" + item, "value"));
				if ((num4.HasValue && num4 != 0.0) || (num5.HasValue && num5 != 0.0) || (num6.HasValue && num6 != 1E+35))
				{
					ShowMessageBoxEventArgs e = new ShowMessageBoxEventArgs
					{
						Title = GetProductI18nName(),
						MsgBoxButton = MessageBoxButton.YesNoCancel
					};
					string mMFreerad_GetRate_dBank = ApwnResources.MMFreerad_GetRate_dBank;
					mMFreerad_GetRate_dBank = ((num2 <= 1) ? (mMFreerad_GetRate_dBank + "?") : (mMFreerad_GetRate_dBank + " for reaction " + num3 + "?"));
					e.Message = mMFreerad_GetRate_dBank;
					ShowMessageBox(e);
					if (e.DialogResult == MessageBoxResult.Yes)
					{
						ExpandDataPathAndSet("@main.Input.GETRATE.#" + item, "value", "0", 2);
					}
					else if (e.DialogResult == MessageBoxResult.No)
					{
						ExpandDataPathAndSet("@main.Input.GETRATE.#" + item, "value", "0", 1);
					}
				}
				else
				{
					ExpandDataPathAndSet("@main.Input.GETRATE.#" + item, "value", "0", 2);
				}
			}
		}
	}
