		public ImageSource ImageSource
		{
			get
			{
				return _imageSource;
			}
			set
			{
				_imageSource = value;
				OnPropertyChanged("ImageSource");
			}
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			if (string.Equals(subPropertyName, "Value") && pd.Name == "RateModelTerm")
			{
				ImageSource = RateTermEquationImageSourceCache.TryGet(RateModelTerm?.Value as string, RateTermEquationType.Substrate);
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}
	}
