		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			if (string.Equals(subPropertyName, "Value") && pd.Name == "RateModelTerm")
			{
				ImageSource = RateTermEquationImageSourceCache.TryGet(RateModelTerm?.Value as string, RateTermEquationType.Product);
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}
	}
	internal class RateTermEquationImageSourceCache
	{
		private static readonly string ImageFolder = "pack://application:,,,/" + typeof(RateTermEquationImageSourceCache).Assembly.FullName + ";component/Images/Fermentation";

		private static readonly Dictionary<string, string> rateTermEquation_ImageName = new Dictionary<string, string>(StringComparer.InvariantCultureIgnoreCase)
		{
			{ "Substrate_MONOD-MOSER", "monod-moser.png" },
			{ "Substrate_EXT-TESSIER", "ext-tessier.png" },
			{ "Substrate_CONTOIS", "contois.png" },
			{ "Substrate_AIBA", "s_aiba.png" },
			{ "Product_AIBA", "p_aiba.png" },
			{ "Product_ANDREWS", "andrews.png" },
			{ "Product_LOGISTIC", "logistic.png" }
		};

		private static Dictionary<string, ImageSource> rateTermEquation_ImageSource = new Dictionary<string, ImageSource>(StringComparer.InvariantCultureIgnoreCase);

		internal static ImageSource TryGet(string rateTermEquationName, RateTermEquationType type)
		{
			if (string.IsNullOrWhiteSpace(rateTermEquationName))
			{
				return null;
			}
			string key = type.ToString() + "_" + rateTermEquationName;
			if (rateTermEquation_ImageSource.TryGetValue(key, out var value))
			{
				return value;
			}
			rateTermEquation_ImageName.TryGetValue(key, out var value2);
			if (value2 == null)
			{
				rateTermEquation_ImageSource.Add(key, null);
				return null;
			}
			string uriString = ImageFolder + "/" + value2;
			BitmapImage bitmapImage = null;
			try
			{
				bitmapImage = new BitmapImage(new Uri(uriString, UriKind.RelativeOrAbsolute));
			}
			catch (Exception)
			{
			}
			if (bitmapImage == null || !bitmapImage.CanFreeze)
			{
				rateTermEquation_ImageSource.Add(key, null);
				return null;
			}
			bitmapImage.Freeze();
			rateTermEquation_ImageSource.Add(key, bitmapImage);
			return bitmapImage;
		}
	}
	internal enum RateTermEquationType
	{
		Substrate,
		Product
	}
