		private void cmdGelEff_CommandExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.EMRTYPE.@CURRXN", "value"));
			if (string.IsNullOrEmpty(text))
			{
				return;
			}
			switch (text)
			{
			case "INIT-DEC":
			case "INIT-CAT":
			case "INIT-SP":
			case "CHAIN-INI":
				text = "INITIATION";
				break;
			case "TERM-DIS":
			case "TERM-COMB":
				text = "TERMINATION";
				break;
			}
			bool flag = true;
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.GETYPE", "child_ids"));
			string text2 = string.Empty;
			if (array != null && array.Length != 0)
			{
				string[] array2 = array;
				foreach (string text3 in array2)
				{
					if (CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.GETYPE." + text3, "value")) == text)
					{
						text2 = text3;
						flag = false;
					}
				}
			}
			if (flag)
			{
				if (array == null)
				{
					AddChild("@main.Input.GETYPE", 0);
					text2 = "#0";
				}
				else
				{
					AddChild("@main.Input.GETYPE", array.Length);
					text2 = "#" + array.Length;
				}
				ExpandDataPathAndSet("@main.Input.GETYPE." + text2, "value", text);
			}
			ExpandDataPathAndSet("@main.Input.OGELEF", "value", "YES");
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMEmulsion.MMEmulsion_React_Gelef1";
			e.LegacyFlags = 0;
			e.HelpId = 40;
			e.HelpFile = "polyfrms.hlp";
			e.ShowPrompts = true;
			e.CompleteDataPaths = new string[1] { "@main.CC Nodes.GELNOD" };
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Gel_Effect;
			e.Parameters.Add("GELRXN", text2);
			e.ResizeMode = ResizeMode.CanResize;
			DisplayForm(e);
		}

		private bool cmdPrev_CanExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			return int.Parse(text.Substring(1)) != 0;
		}

		private void cmdPrev_CommandExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			if (!string.IsNullOrEmpty(text))
			{
				int num = int.Parse(text.Substring(1));
				if (num != 0)
				{
					ResolveUpdateParameter("CURRXN", "#" + (num - 1));
					OnUpdateData();
				}
			}
		}

		private bool cmdNext_CanExecute(object parameter)
		{
			string text = CxsConverter.ValueToString(ResolveParameter("CURRXN"));
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			int num = int.Parse(text.Substring(1));
			int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.EMRTYPE", "child_count"));
			if (num2.HasValue && num2.HasValue && num < num2.Value - 1)
			{
				return true;
			}
			return false;
		}

		private void cmdNext_CommandExecute(object parameter)
		{
			int num = int.Parse(CxsConverter.ValueToString(ResolveParameter("CURRXN")).Substring(1));
			int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.EMRTYPE", "child_count"));
			if (num2.HasValue && num2.HasValue && num < num2.Value - 1)
			{
				ResolveUpdateParameter("CURRXN", "#" + (num + 1));
				OnUpdateData();
			}
		}

		private void cmdEClose_CommandExecute(object parameter)
		{
			CloseForm();
		}

		protected override void OnUpdateData()
		{
			if (base.IsInitialUpdate)
			{
				storParam_FillRxnString();
				PolyRedoLabels();
			}
			SelectedReaction = storParam_GenerateRxnString(CxsConverter.ValueToString(ResolveParameter("CURRXN")));
			base.OnUpdateData();
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			if (propertyName == "SelectedReaction")
			{
				string selectedReaction = _selectedReaction;
				try
				{
					if (!string.IsNullOrEmpty(selectedReaction) && selectedReaction.IndexOf(')') > 0)
					{
						string value = "#" + (int.Parse(selectedReaction.Substring(0, selectedReaction.IndexOf(')'))) - 1);
						ResolveUpdateParameter("CURRXN", value);
					}
				}
				catch
				{
				}
				PolyRedoLabels();
				(cmdPrev_Command as DelegateCommand<object>).RaiseCanExecuteChanged();
				(cmdNext_Command as DelegateCommand<object>).RaiseCanExecuteChanged();
			}
			base.OnPropertyChanged(propertyName);
		}

		private void PolyRedoLabels()
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.EMRTYPE.@CURRXN", "value"));
			switch (text)
			{
			case "CHAT-MON":
			case "TERM-DIS":
			case "INIT-CAT":
			case "INIT-DEC":
			case "CHAT-POL":
			case "CHAIN-INI":
			case "TERM-COMB":
			case "CHAT -SOL":
			case "INIT-SP":
			case "PROPAGATION":
			case "CHAT-AGENT":
				ResolveUpdateParameter("CmdGel", "1");
				break;
			default:
				ResolveUpdateParameter("CmdGel", "0");
				break;
			}
			switch (text)
			{
			case "INIT-DEC":
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Initiator1);
				ResolveUpdateParameter("lblAddCid2", "");
