				ResolveUpdateParameter("lblAddCid2", "");
				break;
			case "TERM-DIS":
				ResolveUpdateParameter("lblAddCid1", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Active_Segment1);
				ResolveUpdateParameter("lblAddCid2", AspenTech.AspenPlus.Localization.Properties.Resources.React_Label_Active_Segment1);
