			e.CompleteDataPaths = new string[1] { "CRYSTAL" };
			e.HelpFile = "Reaction.chm";
			e.HelpId = 310;
			DisplayFormEventArgs e2 = e;
			e2.Parameters.Add("reactionNoPassed", num4);
			DisplayForm(e2);
		}

		private void ReorderReactions()
		{
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
			if (array == null)
			{
				return;
			}
			for (int i = 0; i != array.Length; i++)
			{
				if (array[i] != (i + 1).ToString())
