		private void DeleteCommand_Execute(object parameter)
		{
			IEnumerable<string> enumerable = null;
			if (parameter != null)
			{
				enumerable = new List<string> { parameter as string };
			}
			else if (_selectedRowIndexes != null && _selectedRowIndexes.Count > 0)
			{
				enumerable = from index in _selectedRowIndexes
					let dataList = rxn_GridData as IList
					let itemTemplate = dataList[index] as rxn_GridData_ItemTemplate
					orderby index
					select itemTemplate.ResolveViewPropertyPath("rxnNo.Value") as string;
			}
			string[] source = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.KEY_CID", "child_ids"));
			List<string> list = new List<string>();
			List<string> list2 = source.ToList();
			List<string> selectedSolutesFromRemaining = new List<string>();
			foreach (string item in enumerable)
			{
				list.Add(CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.KEY_CID." + item, "value")));
				list2.Remove(item);
			}
			foreach (string item2 in list2)
			{
				selectedSolutesFromRemaining.Add(CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.KEY_CID." + item2, "value")));
			}
			IEnumerable<string> children = list.Where((string x) => !selectedSolutesFromRemaining.Contains(x));
			string text = null;
			text = ((enumerable.Count() > 1) ? ApwnResources.ConfirmDeleteReactions : (string.IsNullOrEmpty(parameter as string) ? (AspenTech.AspenPlus.MMControls.Properties.Resources.Delete + " " + enumerable.ElementAt(0) + "?") : (AspenTech.AspenPlus.MMControls.Properties.Resources.Delete + " " + parameter?.ToString() + "?")));
			ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
			{
				Title = AspenTech.AspenPlus.MMControls.Properties.Resources.Confirm,
				Message = text,
				MsgBoxButton = 1,
				MsgBoxImage = 32,
				DialogResult = 1
			};
			ShowMMMessageBox(e);
			if (e.DialogResult == 1)
			{
				DeleteChildren("@main.Input.COEF", enumerable, silently: true);
				DeleteChildren("@main.Input.SOLUB_A", children, silently: true);
			}
		}
