		public ObservableCollection<int> SelectedRowIndexes
		{
			get
			{
				return _selectedRowIndexes;
			}
			set
			{
				if (value != _selectedRowIndexes)
				{
					_selectedRowIndexes = value;
				}
			}
		}

		public int AllSelectedRecordsCount
		{
			get
			{
				return _allSelectedRecordsCount;
			}
			set
			{
				if (value != _allSelectedRecordsCount)
				{
					_allSelectedRecordsCount = value;
					OnAllSelectedRecordsCountChanged();
				}
			}
		}

		public ICommand DeleteCommand
		{
			get
			{
				if (_deleteCommand == null)
				{
					_deleteCommand = new DelegateCommand<object>(DeleteCommand_Execute, DeleteCommand_CanExecute);
				}
				return _deleteCommand;
			}
		}

		public object selectedReactionParameter => GetValue(selectedReactionParameter_Property);

		public object selectedSaltParameter => GetValue(selectedSaltParameter_Property);

		public event EventHandler AllSelectedRecordsCountChanged;

		private void OnAllSelectedRecordsCountChanged()
		{
			if (this.AllSelectedRecordsCountChanged != null)
			{
				this.AllSelectedRecordsCountChanged(this, EventArgs.Empty);
			}
			OnPropertyChanged("AllSelectedRecordsCount");
		}

		private bool DeleteCommand_CanExecute(object args)
		{
			return true;
		}

		private void DeleteCommand_Execute(object parameter)
		{
			IEnumerable<string> children = null;
			if (parameter != null)
			{
				children = new List<string> { parameter.ToString() };
			}
			else if (_selectedRowIndexes != null && _selectedRowIndexes.Count > 0)
			{
				children = from index in _selectedRowIndexes
					let dataList = nucleationReaction_GridData as IList
					let itemTemplate = dataList[index] as nucleationReaction_GridData_ItemTemplate
					orderby index
					select itemTemplate.ResolveViewPropertyPath("indexLabel.Value") as string;
			}
			DeleteChildren("@main.Input.NP_SAT_EXP.@selectedReaction.@selectedSalt", children);
			base.ResolvedCxsProvider.UpdateDataCache();
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			if (pd.Name == "selectedReactionParameter" && subPropertyName == "Value")
			{
				updateSaltParameter();
			}
			else if (pd.Name == "nucleationReaction_GridData" && subPropertyName == "Count")
			{
				SetNuclid("@main.Input.KN.@selectedReaction.@selectedSalt");
			}
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}

		private void updateSaltParameter()
		{
			ResolveUpdateParameter("selectedSalt", ExpandDataPathAndGet("@main.Input.RP_SALT.@selectedReactionParameter", "value"));
		}

		private void SetNuclid(string path)
		{
			Collection<string> collection = CxsConverter.ValueToStringCollection(ExpandDataPathAndGet(path, "child_ids"));
			if (collection == null || collection.Count < 1)
			{
				return;
			}
			int num = 0;
			foreach (string item in collection)
			{
				if (item.Contains("#"))
				{
					base.ResolvedCxsProvider.BatchSet(ExpandDataPath(path) + "." + item, "id", null, (int.Parse(item.Replace("#", "")) + 1).ToString());
					continue;
				}
				CxsDataProvider resolvedCxsProvider = base.ResolvedCxsProvider;
				string path2 = ExpandDataPath(path) + ".#" + num;
				int num2 = ++num;
				resolvedCxsProvider.BatchSet(path2, "id", null, num2.ToString());
			}
		}

		protected override void OnUpdateData()
		{
			base.OnUpdateData();
		}
	}
