		public ICommand DeleteCommand
		{
			get
			{
				if (_deleteCommand == null)
				{
					_deleteCommand = new CxvDelegateCommand<object>(DeleteCommand_Execute);
				}
				return _deleteCommand;
			}
		}

		public CxvLogicalPropertyData DeleteCommand_CanExecute => GetValue(DeleteCommand_CanExecute_Property) as CxvLogicalPropertyData;

		public ObservableCollection<int> SelectedRowIndexes
		{
			get
			{
				return _selectedRowIndexes;
			}
			set
			{
				if (value != _selectedRowIndexes)
				{
					_selectedRowIndexes = value;
				}
			}
		}

		public object selectedSoluteParameter => GetValue(selectedSoluteParameter_Property);

		public object selectedSoluteParameterID => GetValue(selectedSoluteParameterID_Property);

		private void DeleteCommand_Execute(object parameter)
		{
			List<string> list = new List<string>();
			if (parameter != null)
			{
				list = new List<string> { parameter.ToString() };
			}
			else if (_selectedRowIndexes != null && _selectedRowIndexes.Count > 0)
			{
				_selectedRowIndexes.ToList().Sort((int p, int q) => q.CompareTo(p));
				foreach (int selectedRowIndex in _selectedRowIndexes)
				{
					list.Add(selectedRowIndex.ToString());
				}
			}
			ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
			{
				Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
				Message = "Delete?",
				MsgBoxButton = 1,
				MsgBoxImage = 32,
				DialogResult = 1
			};
			ShowMMMessageBox(e);
			if (!e.DialogResult.HasValue || e.DialogResult.Value == 1)
			{
				DeleteChildrenByRowIndex(ExpandDataPath("@main.Input.SOLUB_TEMP.@selectedSolute"), list, silently: true);
			}
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
		}

		protected override void OnSubPropertyDataChanged(CxvPropertyDeclaration pd, string subPropertyName)
		{
			base.OnSubPropertyDataChanged(pd, subPropertyName);
		}
	}
}
