		private void cmdNew_CommandExecute(object parameter)
		{
			string text = "@main.Input.COEF";
			int num = 999;
			int? num2 = CxsConverter.ValueToInt32(ExpandDataPathAndGet(text, "child_count"));
			if (num2.HasValue && num2.HasValue && num2 >= num)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message52, num.ToString()),
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_New_Reaction,
					MsgBoxButton = MessageBoxButton.OK
				});
				return;
			}
			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet(text, "child_ids"));
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			if (array != null)
			{
				num3 = array.Length;
			}
			if (num3 == 0)
			{
				num4 = 1;
				num5 = 0;
			}
			else
			{
				List<string> list = new List<string>(array);
				num4 = list.Count + 1;
				for (int i = 1; i <= list.Count; i++)
				{
					if (!list.Contains(i.ToString()))
					{
						num4 = i;
						break;
					}
				}
				num5 = list.Count;
			}
			AddChild(text, num5);
			ExpandDataPathAndSet(text + ".#" + num5, "id", num4);
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMACMUser.MMACMUser_Input_Edit";
			e.LegacyFlags = 0;
			e.HelpId = 28;
			e.HelpFile = "Reaction.hlp";
			e.ShowPrompts = true;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Stoichiometry;
			e.CompleteDataPaths = new string[2] { "EXP1", "NAME" };
			DisplayFormEventArgs e2 = e;
			e2.Parameters.Add("RXNNO", num4);
			DisplayForm(e2);
		}

		private void cmdEdit_CommandExecute(object parameter)
		{
			if (SelectedRowIndexes == null || SelectedRowIndexes.Count != 1)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message47,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Edit_Reaction,
					MsgBoxButton = MessageBoxButton.OK
				});
				return;
			}
			int index = SelectedRowIndexes[0];
			string value = ((grdStoic_GridData as IList)[index] as grdStoic_GridData_ItemTemplate).ResolveViewPropertyPath("txtRxnNo_reacno.Value") as string;
			int num = 0;
			if (!string.IsNullOrEmpty(value))
			{
				num = Convert.ToInt32(value);
			}
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMACMUser.MMACMUser_Input_Edit";
			e.LegacyFlags = 0;
			e.HelpId = 28;
			e.HelpFile = "Reaction.hlp";
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Edit_Stoichiometry;
			e.ShowPrompts = true;
			e.CompleteDataPaths = new string[2] { "EXP1", "NAME" };
			DisplayFormEventArgs e2 = e;
			e2.Parameters.Add("RXNNO", num);
			DisplayForm(e2);
		}

		private void cmdDelete_CommandExecute(object parameter)
		{
			if (parameter != null)
			{
				List<string> children = new List<string> { parameter as string };
				DeleteChildren("@main.Input.COEF", children);
			}
			else if (_selectedRowIndexes != null && _selectedRowIndexes.Count > 0)
			{
				IEnumerable<string> children2 = from index in _selectedRowIndexes
					let dataList = grdStoic_GridData as IList
					let itemTemplate = dataList[index] as grdStoic_GridData_ItemTemplate
					orderby index
					select itemTemplate.ResolveViewPropertyPath("txtRxnNo_reacno.Value") as string;
				DeleteChildren("@main.Input.COEF", children2);
			}
		}

		private void cmdCopy_CommandExecute(object parameter)
		{
			string mainPath = CxsConverter.ValueToString(ResolveParameter("main", null));
			this.CopyObjectRows(mainPath, "GERNERAL.REACTION", SelectedRowIndexes);
			OnCanPasteChanged();
		}

		private void OnCanPasteChanged()
		{
			if (this.CanPasteChanged != null)
			{
				this.CanPasteChanged(this, EventArgs.Empty);
			}
			OnPropertyChanged("CanPaste");
		}

		private void cmdPaste_CommandExecute(object parameter)
		{
			string mainPath = CxsConverter.ValueToString(ResolveParameter("main", null));
			if (AllSelectedRecordsCount == 1)
			{
				this.PasteObjectRows(mainPath, "GERNERAL.REACTION", SelectedRowIndexes[0]);
			}
			else
			{
				this.PasteObjectRows(mainPath, "GERNERAL.REACTION");
			}
		}

		private void grid_RowDoubleClick(object parameter)
		{
			if (cmdEditCanExecute.Value)
			{
				cmdEdit_CommandExecute(null);
			}
		}
