	public class ReorderController : INotifyPropertyChanged
	{
		private bool _isUpEnabled;

		private bool _isDownEnabled;

		public Visibility MoveUpImageVisibility { get; private set; } = Visibility.Collapsed;

		public Visibility MoveUpDisableImageVisibility { get; private set; } = Visibility.Collapsed;

		public Visibility MoveDownImageVisibility { get; private set; } = Visibility.Collapsed;

		public Visibility MoveDownDisableImageVisibility { get; private set; } = Visibility.Collapsed;

		public bool IsUpEnabled
		{
			get
			{
				return _isUpEnabled;
			}
			set
			{
				_isUpEnabled = value;
				if (_isUpEnabled)
				{
					MoveUpImageVisibility = Visibility.Visible;
					MoveUpDisableImageVisibility = Visibility.Hidden;
				}
				else
				{
					MoveUpImageVisibility = Visibility.Hidden;
					MoveUpDisableImageVisibility = Visibility.Visible;
				}
				OnPropertyChanged("MoveUpImageVisibility");
				OnPropertyChanged("MoveUpDisableImageVisibility");
			}
		}

		public bool IsDownEnabled
		{
			get
			{
				return _isDownEnabled;
			}
			set
			{
				_isDownEnabled = value;
				if (_isDownEnabled)
				{
					MoveDownImageVisibility = Visibility.Visible;
					MoveDownDisableImageVisibility = Visibility.Hidden;
				}
				else
				{
					MoveDownImageVisibility = Visibility.Hidden;
					MoveDownDisableImageVisibility = Visibility.Visible;
				}
				OnPropertyChanged("MoveDownImageVisibility");
				OnPropertyChanged("MoveDownDisableImageVisibility");
			}
		}

		public event PropertyChangedEventHandler PropertyChanged;

		private void OnPropertyChanged(string propertyName = null)
		{
			this.PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
		}
	}
