		public CustomTermsTabPageViewModel()
		{
			ParaDeleteCommand = new CxvDelegateCommand<object>(ParaDeleteCommand_Execute);
			VarDeleteCommand = new CxvDelegateCommand<object>(VarDeleteCommand_Execute);
			EqDeleteCommand = new CxvDelegateCommand<object>(EqDeleteCommand_Execute);
			ReorderUpCommand = new DelegateCommand<object>(ReorderUp_CommandExecute, ReorderUp_CommandCanExecute);
			ReorderDownCommand = new DelegateCommand<object>(ReorderDown_CommandExecute, ReorderDown_CommandCanExecute);
			ReorderController = new ReorderController();
		}

		private void ParaDeleteCommand_Execute(object parameter)
		{
			if (parameter != null && parameter is string text && !string.IsNullOrEmpty(text))
			{
				string message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message49, text);
				ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					Message = message,
					MsgBoxButton = 1,
					MsgBoxImage = 32,
					DialogResult = 1
				};
				ShowMMMessageBox(e);
				if (e.DialogResult == 1)
				{
					DeleteChild("@main.Input.PARM_VALUE", text);
				}
			}
		}

		private void VarDeleteCommand_Execute(object parameter)
		{
			CxvVectorPropertyData cxvVectorPropertyData = Variables as CxvVectorPropertyData;
			int num = -1;
			if (parameter != null && cxvVectorPropertyData.IndexBasis != null && cxvVectorPropertyData.IndexBasis is CxvChildCountIndexBasisData && cxvVectorPropertyData.IndexBasis is CxvChildCountIndexBasisData { ChildIdsVector: not null } cxvChildCountIndexBasisData && cxvChildCountIndexBasisData.ChildIdsVector.Count() > 0)
			{
				int num2 = cxvChildCountIndexBasisData.ChildIdsVector.Count();
				for (int i = 0; i < num2; i++)
				{
					object value = cxvChildCountIndexBasisData.ChildIdsVector.GetValue(i);
					if (parameter.ToString() == value.ToString())
					{
						num = i;
						break;
					}
				}
			}
			string arg = ((num != -1) ? CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.VAR_TYPE.#" + num, "id")) : "#0");
			string message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message49, arg);
			ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
			{
				Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
				Message = message,
				MsgBoxButton = 1,
				MsgBoxImage = 32,
				DialogResult = 1
			};
			ShowMMMessageBox(e);
			if (e.DialogResult == 1 && num != -1)
			{
				DeleteChild("@main.Input.VAR_TYPE", num);
			}
		}

