						RefreshData();
						OnPropertyChanged("MMFrame1_MultiMap");
						OnPropertyChanged("StoicRollerEquilibrium_var1");
						(StoicRollerEquilibrium_var1 as CxvReactionListPropertyData).RefreshData();
					};
				}
