		public MMChemistry_InputC_Equilib_ViewModel()
		{
			GrInqReference = this.GrInqReference();
		}

		protected override void OnUpdateData()
		{
			base.OnUpdateData();
			if (base.IsInitialUpdate)
			{
				if (GrInqReference == 0)
				{
					ResolveUpdateParameter("MMLabelbasis_Var", AspenTech.AspenPlus.Localization.Properties.Resources.MMChemistry_InputC_Equilib_ViewModel__MMLabelbasis_Aqueous_Phase_Infinite_Dilution);
				}
				else
				{
					ResolveUpdateParameter("MMLabelbasis_Var", AspenTech.AspenPlus.Localization.Properties.Resources.MMChemistry_InputC_Equilib_ViewModel__MMLabelbasis_Pure_Fused_Salt_Dilution);
				}
				RefreshData();
			}
		}

		private void RefreshData()
		{
			ResolveUpdateParameter("txtnosalt_Visible", false);
			ResolveUpdateParameter("txtnosalt_Enable", false);
			if (varHSDependencies != null)
			{
				varHSDependencies.PropertyDependencyChanged -= varHSDependencies_PropertyDependencyChangedHandler;
			}
			if (varHSDependencies != null)
			{
				varHSDependencies.Clear();
			}
			else
			{
				varHSDependencies = new CxvPropertyWatch();
			}
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.COEF", "child_count", null, varHSDependencies));
			if (num.HasValue)
			{
				if (num != 0)
				{
					ResolveUpdateParameter("EquilibriumConstants", "MMFrame1_MultiMapOption_1");
				}
				else if (CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.SALT_COEF", "child_count", null, varHSDependencies)) != 0)
				{
					ResolveUpdateParameter("EquilibriumConstants", "MMFrame1_MultiMapOption_2");
				}
				else
				{
					ResolveUpdateParameter("EquilibriumConstants", "MMFrame1_MultiMapOption_1");
				}
			}
			if (!varHSDependencies.IsEmpty)
			{
				varHSDependencies.PropertyDependencyChanged += varHSDependencies_PropertyDependencyChangedHandler;
			}
			else
			{
				varHSDependencies = null;
			}
		}
	}
