		public class grdStoic_GridData_ItemTemplate : MMViewModel
		{
			private readonly CxvPropertyWatch watch = new CxvPropertyWatch();

			public static readonly CxvPropertyDeclaration txtRxnID_var1_Property = CxvPropertyDeclaration.Register("txtRxnID_var1", typeof(grdStoic_GridData_ItemTemplate), new CxvVariableProperty
			{
				DataPath = "@main.Input.RXNID.@y"
			});

			public static readonly CxvPropertyDeclaration MMTextBox1_var1_Property = CxvPropertyDeclaration.Register("MMTextBox1_var1", typeof(grdStoic_GridData_ItemTemplate), new CxvVariableProperty
			{
				DataPath = "@main.Input.RXNSTRING.@y"
			});

			public object txtRxnType_var1 => new CxvManualVariableData
			{
				IsReadOnly = true,
				Value = txtRxnType
			};

			public string txtRxnType
			{
				get
				{
					string result = "";
					watch.PropertyDependencyChanged -= watch_PropertyDependencyChanged;
					watch.Clear();
					string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.RXNTYPE.@y", "value", null, watch));
					if (text == "")
					{
						return result;
					}
					if (text == "Equilibrium")
					{
						result = ApwnResources.MMChemistry_Input_New_MMF_Content0;
					}
					if (text == "Dissociation")
					{
						result = ApwnResources.MMChemistry_Input_New_MMF_Content2;
					}
					if (text == "Salt")
					{
						result = ApwnResources.MMChemistry_Input_New_MMF_Content1;
					}
					if (!watch.IsEmpty)
					{
						watch.PropertyDependencyChanged += watch_PropertyDependencyChanged;
					}
					return result;
				}
			}

			public object txtRxnID_var1 => GetValue(txtRxnID_var1_Property);

			public object MMTextBox1_var1 => GetValue(MMTextBox1_var1_Property);

			private void watch_PropertyDependencyChanged(object sender, EventArgs e)
			{
				OnPropertyChanged("txtRxnType_var1");
			}

			public string GetId()
			{
				return CxsConverter.ValueToString(ResolveViewPropertyPath("txtRxnID_var1.Value", null));
			}

			public string GetRxnType()
			{
				return CxsConverter.ValueToString(ResolveViewPropertyPath("txtRxnType_var1.Value", null));
			}
		}

