		private void cmdDelete_CommandExecute(object parameter)
		{
			Collection<string> collection = new Collection<string>();
			string text = parameter as string;
			if (!string.IsNullOrEmpty(text))
			{
				collection.Add(text);
			}
			else
			{
				List<int> list = new List<int>();
				foreach (int selectedRowIndex in SelectedRowIndexes)
				{
					if (list.Count <= 0)
					{
						list.Add(selectedRowIndex);
						continue;
					}
					for (int i = 0; i < list.Count; i++)
					{
						if (selectedRowIndex > list[i])
						{
							list.Insert(i, selectedRowIndex);
							break;
						}
						if (i == list.Count - 1)
						{
							list.Add(selectedRowIndex);
							break;
						}
					}
				}
				for (int j = 0; j < list.Count; j++)
				{
					int position = list[j];
					string id = GetId(position);
					collection.Add(id);
				}
			}
			DeleteChildren(new string[3] { "@main.Input.COEF", "@main.Input.SALT_COEF", "@main.Input.DISS_COEF" }, collection);
			IList list2 = grdStoic_GridData as IList;
			if (SelectedRowIndexes != null && SelectedRowIndexes.Count > 0 && list2 != null && SelectedRowIndexes[0] >= list2.Count)
			{
				SelectedRowIndexes.Clear();
				SelectedRowIndexes.Add(0);
			}
		}

		private void DeleteChildren(IEnumerable<string> parentPath, IEnumerable<string> children)
		{
			string msgBox_Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message48;
			bool flag = false;
			List<string> list = new List<string>();
			for (int i = 0; i < children.Count(); i++)
			{
				if (flag)
				{
					list.Add(children.ElementAt(i));
					continue;
				}
				msgBox_Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message49, children.ElementAt(i));
				ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Confirm,
					Message = msgBox_Message,
					MsgBoxButton = ((children.Count() == 1) ? 1 : 13),
					MsgBoxImage = 32,
					DialogResult = 1
				};
				ShowMMMessageBox(e);
				if (children.Count() == 1)
				{
					if (e.DialogResult == 1)
					{
						list.Add(children.ElementAt(i));
					}
					continue;
				}
				flag = e.DialogResult == 14;
				bool num = e.DialogResult == 15;
				if (e.DialogResult == 6 || flag)
				{
					list.Add(children.ElementAt(i));
				}
				if (num)
				{
					break;
				}
				if (e.DialogResult == 2)
				{
					list.Clear();
					break;
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			foreach (string item in list)
			{
				foreach (string item2 in parentPath)
				{
					InvokeAction(item2, "DeleteChild", true, item);
				}
			}
			UpdateDisplay();
			UpdateAll();
		}

