		private void cmdOK_CommandExecute(object parameter)
		{
			if (!(base.View is MMChemistry_Input_New mMChemistry_Input_New))
			{
				return;
			}
			bool? isChecked = mMChemistry_Input_New.optEquilibrium.IsChecked;
			bool? isChecked2 = mMChemistry_Input_New.optSalt.IsChecked;
			bool? isChecked3 = mMChemistry_Input_New.optDissociation.IsChecked;
			if (isChecked.HasValue && isChecked == true)
			{
				string text = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.TEXT", "value"));
				if (string.IsNullOrEmpty(text))
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message42,
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Reaction_Number,
						MsgBoxButton = MessageBoxButton.OK
					});
					return;
				}
				int num = Convert.ToInt32(text);
				if (num < 1 || num > 999)
				{
					ExpandDataPathAndSet("@main.Input.TEXT", "value", SaveID);
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message43,
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Reaction_Number,
						MsgBoxButton = MessageBoxButton.OK
					});
					return;
				}
				int location = 0;
				string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
				bool flag = false;
				if (array != null)
				{
					location = array.Length;
					string[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						if (array2[i] == text)
						{
							flag = true;
							break;
						}
					}
				}
				if (flag)
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message44, text),
						Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Specify_Reaction_Number,
						MsgBoxButton = MessageBoxButton.OK
					});
					return;
				}
				AddChild("@main.Input.COEF", location);
				ExpandDataPathAndSet("@main.Input.COEF.#" + location, "id", text);
				DisplayFormEventArgs e = new DisplayFormEventArgs
				{
					FormProgId = "MMChemistry.MMChemistry_Input_EditEqui",
					LegacyFlags = 32,
					HelpId = 277,
					ShowPrompts = true,
					ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Equilibrium_Reaction_Stoichiometry
				};
				e.HelpFile = "REACTION.HLP";
				if (GetProductCode() == 2)
				{
					e.HelpFile = "APR-REACTION.CHM";
				}
