			string[] array = CxsConverter.ValueToStringArray(ExpandDataPathAndGet("@main.Input.COEF", "child_ids"));
			if (array != null && array.Length != 0)
			{
				List<int> list = new List<int>();
				string[] array2 = array;
				foreach (string value in array2)
				{
					list.Add(Convert.ToInt32(value));
				}
				list.Sort();
				int num2 = list[list.Count - 1];
				for (int j = 1; j <= num2 + 1; j++)
				{
					if (!list.Contains(j))
					{
						num = j;
						break;
					}
				}
			}
			ExpandDataPathAndSet("@main.Input.TEXT", "value", num);
			SaveID = num;
		}

