		private void cmdNew_CommandExecute(object parameter)
		{
			MMChemistry_Input_New_ViewModel.isFirstRunKineticCommand = true;
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMChemistry.MMChemistry_Input_New";
			e.LegacyFlags = 0;
			e.ShowPrompts = false;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Select_Reaction_Type;
			DisplayForm(e);
		}

		private void cmdEdit_CommandExecute(object parameter)
		{
			if (SelectedRowIndexes == null || SelectedRowIndexes.Count <= 0)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message47,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Caption_Edit_Reaction,
					MsgBoxButton = MessageBoxButton.OK
				});
				return;
			}
			int position = SelectedRowIndexes[0];
			string id = GetId(position);
			string type = GetType(position);
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.Parameters.Add("RXNNO", id);
			if (type.Equals(ApwnResources.MMChemistry_Input_New_MMF_Content0, StringComparison.InvariantCultureIgnoreCase))
			{
				e.FormType = typeof(MMChemistry_Input_EditEqui);
				e.LegacyFlags = 0;
				e.ShowPrompts = true;
				e.HelpId = 277;
				if (GetProductCode() == 2)
				{
					e.HelpFile = "APR-REACTION.CHM";
				}
				else
				{
					e.HelpFile = "REACTION.HLP";
				}
				e.CompleteDataPaths = new string[1] { "REAC" };
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Equilibrium_Reaction_Stoichiometry;
			}
			else if (type.Equals(ApwnResources.MMChemistry_Input_New_MMF_Content1, StringComparison.InvariantCultureIgnoreCase))
			{
				e.FormType = typeof(MMChemistry_Input_EditSalt);
				e.LegacyFlags = 0;
				e.ShowPrompts = true;
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Salt_Dissolution_Stoichiometry;
				e.HelpId = 279;
				if (GetProductCode() == 2)
				{
					e.HelpFile = "APR-REACTION.CHM";
				}
				else
				{
					e.HelpFile = "REACTION.HLP";
				}
				e.CompleteDataPaths = new string[1] { "SALTREAC" };
			}
			else
			{
				if (!type.Equals(ApwnResources.MMChemistry_Input_New_MMF_Content2, StringComparison.InvariantCultureIgnoreCase))
				{
					return;
				}
				e.FormType = typeof(MMChemistry_Input_EditDiss);
				e.HelpId = 278;
				e.LegacyFlags = 0;
				e.ShowPrompts = true;
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Electrolyte_Dissociation_Stoichiometry;
				if (GetProductCode() == 2)
				{
					e.HelpFile = "APR-REACTION.CHM";
				}
				else
				{
					e.HelpFile = "REACTION.HLP";
				}
				e.CompleteDataPaths = new string[1] { "DISSREAC" };
			}
			DisplayForm(e);
		}

